const section = (title, ...body) => ({title, body});
const example = (title, code, explanation) => ({title, code, explanation});
const practice = (title, ...steps) => ({title, steps});
const lesson = (week, number, title, summary, objectives, sections, codeExample, checkpoints, exercise, sources, minutes=45) => ({
  id:`w${week}-l${number}`, week, title, minutes, summary, objectives, sections,
  example:codeExample, checkpoints, practice:exercise, sources
});

